import requests 
import json 
import xmltodict 
url = "https://example.com/data" 
response = requests.get(url) 
data = json.loads(response.text) 
xml = xmltodict.parse(data) 
matcher = { 
"name": "matcher", 
"criteria": { 
"age": { 
"gt": 0 
} 
} 
} 
matcher["criteria"]["age"]["gt"] = 10 
mapped_data = xml["data"] 
for item in mapped_data: 
if matcher == item: 
print("Matched item:", item) 
